
/* ── Вшитые модели ONNX: при пустой БД страница сама кладёт их в IndexedDB ──
   detection.onnx + cyrillic.onnx + cyrillic.txt (gzip+base64). После первой
   загрузки модели живут в БД; ручной импорт в ⚙ Модели по-прежнему работает
   и перезаписывает вшитые.                                                        */
let DET_GZ_B64 = '';
let REC_GZ_B64 = '';
let CRDICT_GZ_B64 = '';

async function gunzipB64ToArrayBuffer(b64) {
  if (typeof DecompressionStream === 'undefined') {
    throw new Error('браузер не умеет DecompressionStream');
  }
  const packed = b64ToBytes(b64);
  const buf = await new Response(
    new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'))
  ).arrayBuffer();
  return buf;
}

/** Положить вшитые модели в IndexedDB, если их там ещё нет. */
async function seedEmbeddedModels() {
  const have = await DB.get('kv', 'model:det');
  if (have) { freeEmbeddedModels(); return false; }
  if (typeof DET_GZ_B64 !== 'string' || DET_GZ_B64.length < 1000) return false;
  await DB.put('kv', { k: 'model:det', v: await gunzipB64ToArrayBuffer(DET_GZ_B64) });
  await DB.put('kv', { k: 'model:rec', v: await gunzipB64ToArrayBuffer(REC_GZ_B64) });
  const crBytes = await gunzipB64ToArrayBuffer(CRDICT_GZ_B64);
  await DB.put('kv', { k: 'model:dict', v: new TextDecoder('utf-8').decode(new Uint8Array(crBytes)) });
  console.info('модели засеяны из вшитых копий');
  freeEmbeddedModels();
  return true;
}

/** Освободить ~30 МБ: base64-строки моделей живут в куче V8 весь сеанс. */
function freeEmbeddedModels() {
  try {
    if (typeof DET_GZ_B64 === 'string') DET_GZ_B64 = '';
    if (typeof REC_GZ_B64 === 'string') REC_GZ_B64 = '';
    if (typeof CRDICT_GZ_B64 === 'string') CRDICT_GZ_B64 = '';
  } catch (e) { /* const — оставить как есть */ }
}
